with cleaned as (select *, greatest(humidity, temp_c) as greatest_humidity_temp_c, ceil(status_bits) as status_bits_whole from device_readings where reading_ts > timestamp '2025-09-01 03:00:00' and humidity between 59 and 76) select id, device_code, metric_name, val from (select id, device_code, humidity, greatest_humidity_temp_c, temp_c from cleaned) src unpivot (val for metric_name in (humidity, greatest_humidity_temp_c, temp_c)) u
